import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState, AppDispatch } from '../../store/store';
import { fetchAccounts } from '../../store/slices/accountsSlice';
import './AccountsByHour.css';

interface HourlyBreakdown {
  time_slot: string;
  net_pnl: number;
  total_trades: number;
  largest_winner: number;
  largest_loser: number;
  drawdown: number;
  runup: number;
  percent_of_total_trades: number;
  equity_peak: number;
}

const AccountsByHour: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const { accounts, isLoading: accountsLoading } = useSelector((state: RootState) => state.accounts);
  
  const [selectedAccount, setSelectedAccount] = useState<string>('');
  const [selectedSymbol, setSelectedSymbol] = useState<string>('');
  const [hourlyData, setHourlyData] = useState<HourlyBreakdown[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    dispatch(fetchAccounts());
  }, [dispatch]);

  // Get unique account names
  const uniqueAccounts = Array.from(new Set(accounts.map(acc => acc.name)));
  
  // Get symbols for selected account
  const availableSymbols = accounts
    .filter(acc => acc.name === selectedAccount)
    .map(acc => acc.symbol);

  const fetchHourlyBreakdown = async () => {
    if (!selectedAccount || !selectedSymbol) return;
    
    setIsLoading(true);
    setError(null);
    
    try {
      const response = await fetch(
        `http://localhost:3001/api/v1/accounts/${selectedAccount}/hourly-breakdown?symbol=${selectedSymbol}`
      );
      
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      
      const data = await response.json();
      setHourlyData(data.data || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
      setHourlyData([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (selectedAccount && selectedSymbol) {
      fetchHourlyBreakdown();
    }
  }, [selectedAccount, selectedSymbol]);

  // Auto-select first symbol when account changes
  useEffect(() => {
    if (selectedAccount && availableSymbols.length > 0) {
      setSelectedSymbol(availableSymbols[0]);
    }
  }, [selectedAccount]);

  const formatCurrency = (value: number): string => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(value);
  };

  const formatPercentage = (value: number): string => {
    return `${value.toFixed(2)}%`;
  };

  return (
    <div className="accounts-by-hour">
      <h1>Accounts by Hour</h1>
      <p>30-minute interval breakdown based on trade entry time (matching SierraChart logic)</p>
      
      <div className="controls">
        <div className="control-group">
          <label htmlFor="account-select">Account:</label>
          <select 
            id="account-select"
            value={selectedAccount}
            onChange={(e) => setSelectedAccount(e.target.value)}
            disabled={accountsLoading}
          >
            <option value="">Select an account...</option>
            {uniqueAccounts.map(account => (
              <option key={account} value={account}>{account}</option>
            ))}
          </select>
        </div>

        {selectedAccount && (
          <div className="control-group">
            <label htmlFor="symbol-select">Symbol:</label>
            <select 
              id="symbol-select"
              value={selectedSymbol}
              onChange={(e) => setSelectedSymbol(e.target.value)}
            >
              <option value="">Select a symbol...</option>
              {availableSymbols.map(symbol => (
                <option key={symbol} value={symbol}>{symbol}</option>
              ))}
            </select>
          </div>
        )}
      </div>

      {isLoading && (
        <div className="loading">Loading hourly breakdown...</div>
      )}

      {error && (
        <div className="error">Error: {error}</div>
      )}

      {hourlyData.length > 0 && (
        <div className="hourly-table">
          <div className="table-header">
            <span>Time</span>
            <span>Net P&L</span>
            <span>Total Trades</span>
            <span>Largest Winner</span>
            <span>Largest Loser</span>
            <span>Drawdown</span>
            <span>Runup</span>
            <span>% of Total Trades</span>
            <span>Equity Peak</span>
          </div>
          
          {hourlyData.map((row, index) => (
            <div key={index} className="table-row">
              <span className="time-slot">{row.time_slot}</span>
              <span className={`pnl ${row.net_pnl >= 0 ? 'positive' : 'negative'}`}>
                {formatCurrency(row.net_pnl)}
              </span>
              <span>{row.total_trades}</span>
              <span className="positive">{formatCurrency(row.largest_winner)}</span>
              <span className="negative">{formatCurrency(row.largest_loser)}</span>
              <span className="negative">{formatCurrency(row.drawdown)}</span>
              <span className="positive">{formatCurrency(row.runup)}</span>
              <span>{formatPercentage(row.percent_of_total_trades)}</span>
              <span>{formatCurrency(row.equity_peak)}</span>
            </div>
          ))}
        </div>
      )}

      {selectedAccount && selectedSymbol && hourlyData.length === 0 && !isLoading && !error && (
        <div className="no-data">
          <h3>No Data Found</h3>
          <p>No trading data found for {selectedAccount} ({selectedSymbol})</p>
        </div>
      )}
    </div>
  );
};

export default AccountsByHour;
